{"args":{"content":""""Password hashing with scrypt (§6). Only the encoded hash is ever stored or exported."""
from __future__ import annotations

import base64
import hashlib
import hmac
import secrets

_N, _R, _P, _LEN = 2**14, 8, 1, 32


def _b64(raw: bytes) -> str:
    return base64.b64encode(raw).decode("ascii")


def hash_password(password: str) -> str:
    salt = secrets.token_bytes(16)
    digest = hashlib.scrypt(password.encode("utf-8"), salt=salt, n=_N, r=_R, p=_P, dklen=_LEN)
    return f"scrypt${_N}${_R}${_P}${_b64(salt)}${_b64(digest)}"


def verify_password(password: str, encoded: str) -> bool:
    try:
        scheme, n, r, p, salt, expected = encoded.split("$")
        if scheme != "scrypt":
            return False
        expected_raw = base64.b64decode(expected)
        digest = hashlib.scrypt(password.encode("utf-8"), salt=base64.b64decode(salt),
                                n=int(n), r=int(r), p=int(p), dklen=len(expected_raw))
    except (ValueError, TypeError):
        return False
    return hmac.compare_digest(digest, expected_raw)


def is_valid_hash(encoded) -> bool:
    """Shape check used when importing state."""
    if not isinstance(encoded, str):
        return False
    parts = encoded.split("$")
    return len(parts) == 6 and parts[0] == "scrypt" and all(parts[1:4]) and all(
        part.isdigit() for part in parts[1:4])


# Verified against when a login names an unknown email, so both failures cost the same.
DUMMY_HASH = hash_password(secrets.token_urlsafe(16))
